const counter = (function () {
  let count = 0;

  return function () {
    count += 1;

    return count;
  };
})();

const twice = (function (fn) {
  fn();

  return fn();
})(counter);

console.log(twice);
console.log(counter());
console.log(typeof counter);
console.log(typeof count);
